function modal() {
 const l=currentLesson;
 if(!l) return "";
 return `<div class="modal-backdrop" data-close><article class="lesson-modal" role="dialog" aria-modal="true"><button class="modal-close" data-close aria-label="Close lesson">×</button><div class="eyebrow">${l.type.toUpperCase()} / ${l.level}</div><h2>${l.title}</h2><p class="modal-lede">${l.desc}</p><div class="modal-meta">${l.time} · ${l.track}</div><div class="modal-content">${l.sections.map((s,i)=>`<section class="modal-note"><span>0${i+1}</span><p>${s}</p></section>`).join("")}</div><div class="note-callout"><b>Think about it</b><p>What changes if this component becomes the bottleneck or fails completely? Write down the assumption you would test first.</p></div><div class="modal-actions"><button class="button-secondary" data-save-modal="${l.id}">${saved.has(l.id)?"★ Saved":"☆ Save lesson"}</button><button class="button-primary" data-close>Back to library <span>↗</span></button></div></article></div>`;
}
async function loadLandingContent() {
 try {
   const response = await fetch(`${API_BASE}/api/content/landing-page`, { headers: { Accept: "application/json" } });
   if (!response.ok) throw new Error(`Landing content API returned ${response.status}`);
   const data = await response.json();
   if (!data?.hero?.diagram?.groups || data?.lab?.status !== "UPCOMING" || !data?.notes?.items) throw new Error("Landing content payload is missing required sections");
   landingContent = data;
   document.title = page === "home" ? (data.meta?.title || "Tech Katta — Distributed Systems & System Design") : "Tech Katta — System Design Learning";
   render();
 } catch (error) {
   console.warn("Using bundled landing-page content fallback:", error);
 }
}
function render() {
 const view = ({home,learn,workspace:architectureWorkspace,interview:mockInterviewPage,practice,evaluate:evaluationPage,questions:questionPage,pricing})[page] || home;
 root.innerHTML = `<div class="app-shell ${page==="home"?"editorial-shell":""}">${header()}${view()}${footer()}${modal()}</div>`;
 if (page === "workspace") bindArchitectureWorkspace(root);
 if (page === "interview") bindMockInterview(root);
 root.querySelectorAll("[data-go]").forEach(el=>el.addEventListener("click",e=>{e.preventDefault();go(el.dataset.go)}));
 root.querySelectorAll("[data-scroll]").forEach(el=>el.addEventListener("click",e=>{const target=el.getAttribute("href");if(target?.startsWith("#")){e.preventDefault();document.querySelector(target)?.scrollIntoView({behavior:"smooth",block:"start"});}}));
 root.querySelectorAll("[data-track]").forEach(el=>el.addEventListener("click",()=>{activeTrack=el.dataset.track==="System design"?"System design":el.dataset.track;showSavedOnly=false;lessonSearchText="";go("learn")}));
 root.querySelectorAll("[data-filter]").forEach(el=>el.addEventListener("click",()=>{activeTrack=el.dataset.filter;showSavedOnly=false;render()}));
 root.querySelectorAll("[data-lesson]").forEach(el=>el.addEventListener("click",()=>{currentLesson=lessons.find(l=>l.id===el.dataset.lesson);render()}));
 root.querySelectorAll("[data-save]").forEach(el=>el.addEventListener("click",()=>{const id=el.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);localStorage.setItem("tk-saved-items",JSON.stringify([...saved]));render()}));
 root.querySelectorAll("[data-saved]").forEach(el=>el.addEventListener("click",()=>{showSavedOnly=!showSavedOnly;lessonSearchText="";activeTrack="All";render()}));
 root.querySelectorAll("[data-close]").forEach(el=>el.addEventListener("click",e=>{if(e.target===el||el.matches("button")){currentLesson=null;render()}}));
 root.querySelectorAll("[data-save-modal]").forEach(el=>el.addEventListener("click",()=>{const id=el.dataset.saveModal;saved.has(id)?saved.delete(id):saved.add(id);localStorage.setItem("tk-saved-items",JSON.stringify([...saved]));render()}));
 const lessonSearch=root.querySelector("#lesson-search"); if(lessonSearch) lessonSearch.addEventListener("input",e=>{lessonSearchText=e.target.value;const pos=e.target.selectionStart;render();const next=root.querySelector("#lesson-search");next.focus();next.setSelectionRange(pos,pos)});
 const qSearch=root.querySelector("#question-search"); if(qSearch) qSearch.addEventListener("input",e=>{questionSearchText=e.target.value;const pos=e.target.selectionStart;render();const next=root.querySelector("#question-search");next.focus();next.setSelectionRange(pos,pos)});
 const qRound=root.querySelector("#question-round"); if(qRound) { qRound.value=questionRound; qRound.addEventListener("change",()=>{questionRound=qRound.value;render()}); }
 root.querySelectorAll("[data-pick-problem]").forEach(el=>el.addEventListener("click",()=>{answers.problem=el.dataset.pickProblem;practiceStep=0;savePracticeSession();render()}));
 root.querySelectorAll("[data-problem]").forEach(el=>el.addEventListener("click",()=>{answers.problem=el.dataset.problem;practiceStep=0;savePracticeSession();go("practice")}));
 root.querySelectorAll("[data-step]").forEach(el=>el.addEventListener("click",()=>{const answer=root.querySelector("#practice-answer");if(answer)answers[practiceStep]=answer.value;practiceStep=Number(el.dataset.step);savePracticeSession();render()}));
 const resetSession=root.querySelector("[data-reset-session]"); if(resetSession) resetSession.addEventListener("click",()=>{answers={};practiceStep=0;savePracticeSession();go("practice")});
 const answer=root.querySelector("#practice-answer"); if(answer) answer.addEventListener("input",e=>{answers[practiceStep]=e.target.value;savePracticeSession()});
 const next=root.querySelector("[data-next]"); if(next) next.addEventListener("click",()=>{if(answer)answers[practiceStep]=answer.value;if(practiceStep<4){practiceStep++;savePracticeSession();render()}else{savePracticeSession();go("evaluate");}});
 const prev=root.querySelector("[data-prev]"); if(prev) prev.addEventListener("click",()=>{if(answer)answers[practiceStep]=answer.value;if(practiceStep>0){practiceStep--;savePracticeSession();render()}});
 const mobile=root.querySelector(".mobile-menu"); if(mobile) mobile.addEventListener("click",()=>root.querySelector(".main-nav")?.classList.toggle("mobile-open"));
}
window.addEventListener("hashchange",()=>{page=location.hash.slice(1)||"home";currentLesson=null;render()});
window.addEventListener("keydown",e=>{if(e.key==="Escape"&&currentLesson){currentLesson=null;render()}});
render();
